shell_commands.command:
cat tests/basics/try_finally_return*.py && cat tests/basics/try_finally_loops.py && ports/unix/build-standard/micropython -c $'class IDGenerator:
 def __init__(self, max_id):
  self._i = 0
  self._mi = max_id
 def get(self):
  try:
   return self._i
  finally:
   self._i += 1
   if self._i > self._mi:
    self._i = 0
print(IDGenerator(10).get())'

git apply --recount <<'PATCH'
diff --git a/py/compile.c b/py/compile.c
--- a/py/compile.c
+++ b/py/compile.c
@@ -1674,13 +1674,14 @@ STATIC void compile_try_finally(compiler_t *comp, mp_parse_node_t pn_body, int n_exce

     compile_increase_except_level(comp, l_finally_block, MP_EMIT_SETUP_BLOCK_FINALLY);

+    // Account for a pending return or UNWIND_JUMP throughout the try and finally blocks.
+    EMIT_ARG(adjust_stack_size, 3);
+
     if (n_except == 0) {
         assert(MP_PARSE_NODE_IS_NULL(pn_else));
-        EMIT_ARG(adjust_stack_size, 3); // stack adjust for possible UNWIND_JUMP state
         compile_node(comp, pn_body);
-        EMIT_ARG(adjust_stack_size, -3);
     } else {
         compile_try_except(comp, pn_body, n_except, pn_except, pn_else);
     }
@@ -1687,6 +1688,7 @@ STATIC void compile_try_finally(compiler_t *comp, mp_parse_node_t pn_body, int n_exce
     compile_node(comp, pn_finally);

     compile_decrease_except_level(comp);
+    EMIT_ARG(adjust_stack_size, -3);
 }
PATCH
